#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

use std::path::{Path, PathBuf};

use tao::{
    dpi::LogicalSize,
    event::{Event, WindowEvent},
    event_loop::{ControlFlow, EventLoop},
    window::WindowBuilder,
};
use wry::{WebContext, WebViewBuilder};

// Generated by build.rs: the Vencord bundle and stylesheet, guarded to run
// only on discord.com.
const INIT_SCRIPT: &str = include_str!(concat!(env!("OUT_DIR"), "/nebula-init.js"));

const APP_NAME: &str = "Nebula";
const DISCORD_URL: &str = "https://discord.com/app";

fn data_dir() -> PathBuf {
    std::env::var_os("APPDATA")
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir)
        .join(APP_NAME)
}

// Create %APPDATA%\Nebula\no-vencord to start Nebula without Vencord.
fn vencord_enabled(data_dir: &Path) -> bool {
    !data_dir.join("no-vencord").exists()
}

fn main() -> wry::Result<()> {
    let event_loop = EventLoop::new();

    let window = WindowBuilder::new()
        .with_title(APP_NAME)
        .with_inner_size(LogicalSize::new(1280.0, 800.0))
        .with_min_inner_size(LogicalSize::new(640.0, 480.0))
        .build(&event_loop)
        .expect("failed to create window");

    let data_dir = data_dir();
    let mut web_context = WebContext::new(Some(data_dir.clone()));

    let mut builder = WebViewBuilder::with_web_context(&mut web_context).with_url(DISCORD_URL);

    #[cfg(debug_assertions)]
    {
        builder = builder.with_devtools(true);
    }

    if vencord_enabled(&data_dir) {
        builder = builder.with_initialization_script(INIT_SCRIPT);
    }

    let webview = builder.build(&window)?;

    event_loop.run(move |event, _, control_flow| {
        *control_flow = ControlFlow::Wait;

        if let Event::WindowEvent {
            event: WindowEvent::CloseRequested,
            ..
        } = event
        {
            *control_flow = ControlFlow::Exit;
        }

        // Keep the window, webview and web context alive for the loop's lifetime.
        let _ = (&window, &webview, &web_context);
    });
}
